ValidationRule.errorConditionFormula:
AND(   
    NOT(
        ISBLANK(
            TEXT(EUSFA_Document_Type__c)
        )
    ),   
    NOT(
        OR(
            CONTAINS(LOWER(FileType), "pdf"),
            CONTAINS(LOWER(FileType), "jpg"),
            CONTAINS(LOWER(FileType), "png"),
            CONTAINS(LOWER(FileType), "jpeg")
        )
    )
)
